CREATE TABLE mixer(
 id text PRIMARY KEY,broadcast_id text NOT NULL REFERENCES broadcast_run(id),stream_id text NOT NULL REFERENCES streaming_stream(id),project_id text NOT NULL,environment_id text NOT NULL,
 state text NOT NULL DEFAULT 'created' CHECK(state IN ('created','preparing','live','degraded','stopping','stopped','failed')),desired_state text NOT NULL DEFAULT 'running' CHECK(desired_state IN ('running','stopped')),
 version integer NOT NULL DEFAULT 1,desired_version integer NOT NULL DEFAULT 0,applied_version integer NOT NULL DEFAULT 0,desired_scene_id text,applied_scene_id text,snapshot jsonb,applied_snapshot jsonb,lost_sources jsonb NOT NULL DEFAULT '[]',last_error text,event_sequence integer NOT NULL DEFAULT 0,
 render_seconds double precision NOT NULL DEFAULT 0,program_seconds double precision NOT NULL DEFAULT 0,input_seconds double precision NOT NULL DEFAULT 0,frames bigint NOT NULL DEFAULT 0,
 created_at timestamptz NOT NULL DEFAULT now(),activated_at timestamptz,stop_requested_at timestamptz,ended_at timestamptz
);
CREATE UNIQUE INDEX mixer_active_stream_idx ON mixer(stream_id) WHERE state NOT IN ('stopped','failed');
CREATE INDEX mixer_scope_idx ON mixer(project_id,environment_id,id);
CREATE TABLE mixer_source(mixer_id text NOT NULL REFERENCES mixer(id),id text NOT NULL,stream_id text NOT NULL REFERENCES streaming_stream(id),PRIMARY KEY(mixer_id,id));
CREATE TABLE mixer_scene(mixer_id text NOT NULL REFERENCES mixer(id),id text NOT NULL,version integer NOT NULL DEFAULT 1,scene jsonb NOT NULL,PRIMARY KEY(mixer_id,id));
CREATE TABLE mixer_overlay(id text PRIMARY KEY,mixer_id text NOT NULL REFERENCES mixer(id),name text NOT NULL,width integer NOT NULL CHECK(width BETWEEN 1 AND 640),height integer NOT NULL CHECK(height BETWEEN 1 AND 360),size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 1048576),sha256 text NOT NULL,object_key text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','ready','deleting','deleted')),created_at timestamptz NOT NULL DEFAULT now(),deletion_requested_at timestamptz);
CREATE INDEX mixer_overlay_owner_idx ON mixer_overlay(mixer_id,state);
ALTER TABLE streaming_session ADD COLUMN mixer_id text REFERENCES mixer(id);
CREATE TABLE mixer_render_session(mixer_id text NOT NULL REFERENCES mixer(id),session_id text NOT NULL REFERENCES streaming_session(id),generation integer NOT NULL,sequence integer NOT NULL DEFAULT 0,candidate_revision integer NOT NULL DEFAULT 0,candidate_sequence integer NOT NULL DEFAULT 0,frames bigint NOT NULL DEFAULT 0,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,PRIMARY KEY(session_id,generation));
CREATE TABLE mixer_usage(mixer_id text NOT NULL REFERENCES mixer(id),session_id text NOT NULL,generation integer NOT NULL,sequence integer NOT NULL,render_seconds double precision NOT NULL CHECK(render_seconds>=0),program_seconds double precision NOT NULL CHECK(program_seconds>=0),input_seconds double precision NOT NULL CHECK(input_seconds>=0),frames integer NOT NULL CHECK(frames>=0),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(session_id,generation,sequence));
CREATE TABLE mixer_operation(id text PRIMARY KEY,mixer_id text NOT NULL REFERENCES mixer(id),kind text NOT NULL CHECK(kind IN ('activate','stop')),revision integer NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','failed')),error_code text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX mixer_operation_owner_idx ON mixer_operation(mixer_id,status);
CREATE FUNCTION validate_mixer_parent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND (NEW.broadcast_id<>OLD.broadcast_id OR NEW.stream_id<>OLD.stream_id OR NEW.project_id<>OLD.project_id OR NEW.environment_id<>OLD.environment_id) THEN RAISE EXCEPTION 'Immutable mixer ownership'; END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM broadcast_run b JOIN streaming_stream s ON s.id=b.stream_id WHERE b.id=NEW.broadcast_id AND b.stream_id=NEW.stream_id AND s.project_id=NEW.project_id AND s.environment_id=NEW.environment_id AND s.status='active') THEN RAISE EXCEPTION 'Invalid mixer ownership'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER mixer_parent_guard BEFORE INSERT OR UPDATE ON mixer FOR EACH ROW EXECUTE FUNCTION validate_mixer_parent();
CREATE FUNCTION validate_mixer_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM mixer m JOIN streaming_stream s ON s.id=NEW.stream_id WHERE m.id=NEW.mixer_id AND s.project_id=m.project_id AND s.environment_id=m.environment_id AND s.status='active') THEN RAISE EXCEPTION 'Invalid mixer source scope'; END IF; RETURN NEW; END $$;
CREATE TRIGGER mixer_source_guard BEFORE INSERT OR UPDATE ON mixer_source FOR EACH ROW EXECUTE FUNCTION validate_mixer_source();
CREATE FUNCTION retire_mixers() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.status<>'active' THEN
 UPDATE mixer SET desired_state='stopped',state=CASE WHEN state IN ('stopped','failed') THEN state ELSE 'stopping' END,stop_requested_at=coalesce(stop_requested_at,now()) WHERE stream_id=NEW.id;
 UPDATE mixer_overlay SET state='deleting',deletion_requested_at=now() WHERE mixer_id IN(SELECT id FROM mixer WHERE stream_id=NEW.id) AND state<>'deleted';
 END IF; RETURN NEW; END $$;
CREATE TRIGGER mixer_owner_retirement AFTER UPDATE OF status ON streaming_stream FOR EACH ROW EXECUTE FUNCTION retire_mixers();

ALTER TABLE webhook_event DROP CONSTRAINT webhook_event_type_check;
ALTER TABLE webhook_event ADD CONSTRAINT webhook_event_type_check CHECK(event_type IN ('room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed'));
ALTER TABLE webhook_endpoint DROP CONSTRAINT webhook_endpoint_event_types_check;
ALTER TABLE webhook_endpoint ADD CONSTRAINT webhook_endpoint_event_types_check CHECK(cardinality(event_types) BETWEEN 1 AND 60 AND array_position(event_types,NULL) IS NULL AND event_types <@ ARRAY['room.created', 'room.started', 'room.ended', 'participant.joined', 'participant.left', 'participant.reconnected', 'track.published', 'track.unpublished', 'connection.degraded', 'connection.recovered', 'stream.created', 'stream.starting', 'stream.live', 'stream.reconnecting', 'stream.ended', 'stream.failed', 'broadcast.created', 'broadcast.starting', 'broadcast.live', 'broadcast.reconnecting', 'broadcast.output_degraded', 'broadcast.stopped', 'broadcast.failed', 'destination.created', 'destination.connected', 'destination.disconnected', 'destination.retrying', 'destination.failed', 'recording.started', 'recording.segment_committed', 'recording.finalizing', 'recording.ready', 'recording.failed', 'recording.deleted', 'schedule.created','schedule.updated','schedule.starting','schedule.started','schedule.missed','schedule.cancelled','schedule.failed','schedule.completed','schedule.reminder','restream.probing','restream.source_connected','restream.source_lost','restream.recovering','restream.stopped','restream.failed','clip.requested','clip.rendering','clip.ready','clip.failed','clip.deleted','mixer.started','mixer.scene_activated','mixer.source_lost','mixer.overloaded','mixer.stopped','mixer.failed']::text[]);


CREATE INDEX mixer_usage_retention_idx ON mixer_usage(created_at);
CREATE INDEX mixer_operation_retention_idx ON mixer_operation(completed_at) WHERE status<>'pending';
CREATE INDEX mixer_overlay_live_idx ON mixer_overlay(state,created_at) WHERE state IN ('pending','ready','deleting');
